-- 0077 — PREFLIGHT. READ ONLY: one SELECT, changes nothing. Generated by supabase/live/make_blocks_pack.sh — do not edit by hand.
-- Run immediately before 0077, and only once the website that calls staff_block is live for this database
-- (staging: the m3-dev preview; live: production) and the desk has reloaded its pages.
-- Part 1: every row must be ok = true, or 0077 is not applied. Part 2: information only.
with checks(part, item, ok, detail) as (
  select 1, 'signed-in users can still insert, update, delete and read blocks directly (what 0077 changes, and its rollback restores)', has_table_privilege('authenticated', 'public.blocks', 'INSERT') and has_table_privilege('authenticated', 'public.blocks', 'UPDATE') and has_table_privilege('authenticated', 'public.blocks', 'DELETE') and has_table_privilege('authenticated', 'public.blocks', 'SELECT'), ''
  union all select 1, 'staff_block: the verified 0076 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1e8dc62bedc9d9bbadcfd68cd906b71d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block'), 'missing')
  union all select 1, 'assert_valid_block: the verified 0076 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '443366cc1f3829e0bc3991c238b5c90c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_block'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_block'), 'missing')
  union all select 1, 'blocks_direct_write_rules: the verified 0076 version', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '58ae4fef2de6a7daaca5d9a48b639525' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'blocks_direct_write_rules'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'blocks_direct_write_rules'), 'missing')
  union all select 1, 'reject_block_over_booking: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '18c335039c80db474319e30ddbde01ec' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_block_over_booking'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_block_over_booking'), 'missing')
  union all select 1, 'reject_booking_over_block: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '1c955f6aaf4eed5d27a8be8032ca149f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_booking_over_block'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'reject_booking_over_block'), 'missing')
  union all select 1, 'expire_stale_holds: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'bd5333a933065bffc0599dcee74b389d' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'expire_stale_holds'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'expire_stale_holds'), 'missing')
  union all select 1, 'assert_valid_court_slot: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '842d14da33899a48cb53eb356bdf671c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'assert_valid_court_slot'), 'missing')
  union all select 1, 'close_club: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '5374dc2a493362cdc644fb0c65256f42' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'close_club'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'close_club'), 'missing')
  union all select 1, 'is_staff_of: unchanged', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '2fd33ea362331532c1508cdb70777296' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'is_staff_of'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'is_staff_of'), 'missing')
  union all select 1, 'staff_block: owner rights, fixed search path, signed-in users only', coalesce(has_function_privilege('authenticated', to_regprocedure('public.staff_block(uuid,uuid,timestamptz,timestamptz,text)'), 'execute') and not has_function_privilege('anon', to_regprocedure('public.staff_block(uuid,uuid,timestamptz,timestamptz,text)'), 'execute') and (select prosecdef and proconfig = '{search_path=public}' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'staff_block') and not has_function_privilege('anon', to_regprocedure('public.assert_valid_block(uuid,uuid,timestamptz,timestamptz)'), 'execute'), false), ''
  union all select 1, 'blocks policies are still the 0075/0076 ones', (select coalesce(string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname), 'none') from pg_policies where schemaname = 'public' and tablename = 'blocks') = 'blocks: staff read (SELECT), blocks: staff write (ALL)', (select coalesce(string_agg(policyname || ' (' || cmd || ')', ', ' order by policyname), 'none') from pg_policies where schemaname = 'public' and tablename = 'blocks')
  union all select 1, '0077 not applied yet (no blocks_direct_insert_refused)', not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'blocks_direct_insert_refused'), (select coalesce(string_agg(tgname, ', ' order by tgname), 'none') from pg_trigger where tgrelid = 'public.blocks'::regclass and not tgisinternal)
  union all select 1, 'overlap protection in place', exists (select 1 from pg_trigger where tgrelid = 'public.blocks'::regclass and tgname = 'blocks_booking_check' and tgenabled = 'O') and exists (select 1 from pg_trigger t join pg_proc p on p.oid = t.tgfoid where t.tgrelid = 'public.bookings'::regclass and p.proname = 'reject_booking_over_block' and t.tgenabled = 'O') and exists (select 1 from pg_constraint where conrelid = 'public.blocks'::regclass and conname = 'no_overlapping_blocks' and contype = 'x'), ''
  union all select 2, 'saved blocks (compare with the postcheck: 0077 changes none)', true, (select count(*) || ' blocks, ' || coalesce(md5(string_agg(id::text || '|' || club_id || '|' || court_id || '|' || start_at || '|' || end_at || '|' || coalesce(reason, '') || '|' || created_by || '|' || created_at, ',' order by id)), '-') from public.blocks)
  union all select 2, 'blocks created in the last 24 hours (the new website saves through staff_block)', true, (select count(*)::text from public.blocks where created_at > now() - interval '24 hours')
)
select part, item, ok, detail from checks order by part, item;
